@page "/"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section text-center py-5 mb-4">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Explore our departments, discover courses, and request enrollment — all in one place.</p>
    <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in featuredCourses)
        {
            <div class="col">
                <FeaturedCourseCard Course="course" />
            </div>
        }
    </div>
</section>

<section class="mb-5">
    <h2 class="mb-3">Departments</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var dept in departments)
        {
            <div class="col">
                <DepartmentCard Department="dept" />
            </div>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Course Catalog — Browse Courses</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4 align-items-end">
    <div class="col-md-5">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" class="form-control"
               placeholder="Search by title, code, description, or instructor…"
               value="@Search" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (selectedDepartment is not null)
{
    <div class="alert alert-info d-flex justify-content-between align-items-center">
        <span>Showing courses in <strong>@selectedDepartment.Name</strong></span>
        <a href="courses@(string.IsNullOrEmpty(Search) ? "" : $"?search={Search}")" class="btn btn-sm btn-outline-secondary">Clear Department Filter</a>
    </div>
}

@if (courses.Count == 0)
{
    <div class="alert alert-warning">
        No courses match your search criteria. Try broadening your search or selecting a different department.
    </div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th class="text-center">Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th class="text-center">Availability</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <CourseListItem Course="course" />
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private IReadOnlyList<Department> departments = [];
    private Department? selectedDepartment;

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);

        if (DepartmentId.HasValue)
        {
            selectedDepartment = CatalogService.GetDepartment(DepartmentId.Value);
        }
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request — Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@submittedCourseName</strong> has been received. You will receive a confirmation email at <strong>@Model.Email</strong>.</p>
        <hr />
        <p class="mb-0"><a href="courses">Browse more courses</a> or <a href="enroll">submit another request</a>.</p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            @if (submitFailed)
            {
