            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (selectedDepartment is not null)
{
    <div class="alert alert-info d-flex justify-content-between align-items-center">
        <span>Showing courses in <strong>@selectedDepartment.Name</strong></span>
        <a href="courses@(string.IsNullOrEmpty(Search) ? "" : $"?search={Search}")" class="btn btn-sm btn-outline-secondary">Clear Department Filter</a>
    </div>
}

@if (courses.Count == 0)
{
    <div class="alert alert-warning">
        No courses match your search criteria. Try broadening your search or selecting a different department.
    </div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th class="text-center">Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th class="text-center">Availability</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <CourseListItem Course="course" />
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private IReadOnlyList<Department> departments = [];
    private Department? selectedDepartment;

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);

        if (DepartmentId.HasValue)
        {
            selectedDepartment = CatalogService.GetDepartment(DepartmentId.Value);
        }
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request — Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@submittedCourseName</strong> has been received. You will receive a confirmation email at <strong>@Model.Email</strong>.</p>
        <hr />
        <p class="mb-0"><a href="courses">Browse more courses</a> or <a href="enroll">submit another request</a>.</p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            @if (submitFailed)
            {
                <div class="alert alert-danger">
                    The enrollment request could not be processed. The course may be full or unavailable. Please try a different course.
                </div>
            }

            <div class="card">
                <div class="card-body">
                    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                        <DataAnnotationsValidator />
                        <AntiforgeryToken />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                            <ValidationMessage For="() => Model.StudentName" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., CS123456" />
                            <ValidationMessage For="() => Model.StudentId" />
                        </div>

                        <div class="mb-3">
                            <label for="email" class="form-label">Email Address <span class="text-danger">*</span></label>
                            <InputText id="email" @bind-Value="Model.Email" class="form-control" />
                            <ValidationMessage For="() => Model.Email" />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                                <option value="0">— Select a course —</option>
                                @foreach (var course in courses)
                                {
                                    <option value="@course.Id">@course.Code — @course.Title (@(course.MaxEnrollment - course.CurrentEnrollment) seats left)</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => Model.CourseId" />
                        </div>

                        <div class="mb-3">
                            <label for="comments" class="form-label">Comments (optional)</label>
                            <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
                            <ValidationMessage For="() => Model.Comments" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </EditForm>
                </div>
            </div>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">How It Works</h5>
                    <ol class="small">
                        <li>Fill out the enrollment request form with your details.</li>
                        <li>Select the course you'd like to enroll in.</li>
                        <li>Submit the form — you'll receive a confirmation email.</li>
                        <li>The registrar's office will process your request within 2 business days.</li>
                    </ol>
                    <p class="small text-muted mb-0">Questions? Contact the registrar at <strong>registrar@university.edu</strong>.</p>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private bool submitted;
    private bool submitFailed;
    private string submittedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses()
            .Where(c => c.CurrentEnrollment < c.MaxEnrollment)
            .ToList();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        if (course is null || !CatalogService.SubmitEnrollmentRequest(Model))
        {
            submitFailed = true;
            return;
        }

        submittedCourseName = $"{course.Code} — {course.Title}";
        submitted = true;
    }
}

